```cpp
#include <bits/stdc++.h>
using namespace std;

// 把容易看错的字符统一成一个代表字符：
//   'O' 与 '0' 视为同一个字符，统一记成 '0'
//   'I' 与 'l' 与 '1' 视为同一个字符，统一记成 '1'
// 其余字符一律原样保留（注意小写 'o'、'i' 不参与合并）
static string norm(const string& s) {
    string t = s;
    for (char& c : t) {
        if (c == 'O') c = '0';
        else if (c == 'I' || c == 'l') c = '1';
    }
    return t;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int T;
    cin >> T;
    while (T--) {
        int n;
        string s1, s2;
        cin >> n >> s1 >> s2;              // n 只用来读入，比较时用不到
        cout << (norm(s1) == norm(s2) ? "YES" : "NO") << '\n';
    }
    return 0;
}
```

### 易错点

小写 $o$、$i$ 不在替换范围内；不能把所有字母统一大小写。

